/**
 * SheetJS / XLSX Standalone Local Engine for PhysioFlow PWA
 * 100% Offline Multi-sheet XLSX Workbook Generator & Exporter
 * Compatible with Excel, Google Sheets, LibreOffice, and Numbers
 */
(function (global) {
  'use strict';

  function crc32(uint8) {
    let table = [];
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      }
      table[i] = c;
    }
    let crc = 0 ^ (-1);
    for (let i = 0; i < uint8.length; i++) {
      crc = (crc >>> 8) ^ table[(crc ^ uint8[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
  }

  function concatUint8Arrays(arrays) {
    const totalLength = arrays.reduce((acc, curr) => acc + curr.length, 0);
    const result = new Uint8Array(totalLength);
    let offset = 0;
    for (const arr of arrays) {
      result.set(arr, offset);
      offset += arr.length;
    }
    return result;
  }

  function makeZip(files) {
    const encoder = new TextEncoder();
    const localHeaders = [];
    const cdHeaders = [];
    let offset = 0;

    for (const f of files) {
      const nameBytes = encoder.encode(f.name);
      const dataBytes = (typeof f.data === 'string') ? encoder.encode(f.data) : f.data;
      const crc = crc32(dataBytes);
      const size = dataBytes.length;

      // Local file header (30 bytes + name)
      const lhBytes = new Uint8Array(30 + nameBytes.length);
      const lhView = new DataView(lhBytes.buffer);
      lhView.setUint32(0, 0x04034b50, true);
      lhView.setUint16(4, 20, true);
      lhView.setUint16(6, 0x0800, true); // UTF-8 filename flag
      lhView.setUint16(8, 0, true);      // Method: Store (0)
      lhView.setUint16(10, 0, true);
      lhView.setUint16(12, 0, true);
      lhView.setUint32(14, crc, true);
      lhView.setUint32(18, size, true);
      lhView.setUint32(22, size, true);
      lhView.setUint16(26, nameBytes.length, true);
      lhView.setUint16(28, 0, true);
      lhBytes.set(nameBytes, 30);

      localHeaders.push(lhBytes);
      localHeaders.push(dataBytes);

      // Central directory header (46 bytes + name)
      const cdBytes = new Uint8Array(46 + nameBytes.length);
      const cdView = new DataView(cdBytes.buffer);
      cdView.setUint32(0, 0x02014b50, true);
      cdView.setUint16(4, 20, true);
      cdView.setUint16(6, 20, true);
      cdView.setUint16(8, 0x0800, true); // UTF-8 filename flag
      cdView.setUint16(10, 0, true);     // Method: Store (0)
      cdView.setUint16(12, 0, true);
      cdView.setUint16(14, 0, true);
      cdView.setUint32(16, crc, true);
      cdView.setUint32(20, size, true);
      cdView.setUint32(24, size, true);
      cdView.setUint16(28, nameBytes.length, true);
      cdView.setUint16(30, 0, true);
      cdView.setUint16(32, 0, true);
      cdView.setUint16(34, 0, true);
      cdView.setUint16(36, 0, true);
      cdView.setUint32(38, 0, true);
      cdView.setUint32(42, offset, true);
      cdBytes.set(nameBytes, 46);

      cdHeaders.push(cdBytes);
      offset += lhBytes.length + dataBytes.length;
    }

    const cdStart = offset;
    const cdBytesTotal = concatUint8Arrays(cdHeaders);
    const cdSize = cdBytesTotal.length;
    const count = files.length;

    // End of central directory record (22 bytes)
    const eocdBytes = new Uint8Array(22);
    const eocdView = new DataView(eocdBytes.buffer);
    eocdView.setUint32(0, 0x06054b50, true);
    eocdView.setUint16(4, 0, true);
    eocdView.setUint16(6, 0, true);
    eocdView.setUint16(8, count, true);
    eocdView.setUint16(10, count, true);
    eocdView.setUint32(12, cdSize, true);
    eocdView.setUint32(16, cdStart, true);
    eocdView.setUint16(20, 0, true);

    return concatUint8Arrays([...localHeaders, cdBytesTotal, eocdBytes]);
  }

  function escapeXml(str) {
    return String(str || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  function colToLetter(colIndex) {
    let temp, letter = '';
    while (colIndex >= 0) {
      temp = colIndex % 26;
      letter = String.fromCharCode(temp + 65) + letter;
      colIndex = Math.floor(colIndex / 26) - 1;
    }
    return letter;
  }

  const XLSX = {
    version: '0.18.5',
    utils: {
      book_new: function () {
        return { SheetNames: [], Sheets: {} };
      },
      json_to_sheet: function (data) {
        if (!Array.isArray(data) || !data.length) {
          return { '!rows': [] };
        }
        const headers = Object.keys(data[0]);
        const rows = [headers];
        for (const item of data) {
          const row = headers.map(h => (item[h] !== undefined && item[h] !== null) ? item[h] : '');
          rows.push(row);
        }
        return { '!rows': rows };
      },
      book_append_sheet: function (wb, ws, name) {
        wb.SheetNames.push(name);
        wb.Sheets[name] = ws;
      }
    },
    buildXlsxUint8Array: function (wb) {
      const files = [];

      // 1. _rels/.rels
      files.push({
        name: '_rels/.rels',
        data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' +
          '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\n' +
          '  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>\n' +
          '</Relationships>'
      });

      // 2. xl/_rels/workbook.xml.rels
      let wbRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\n' +
        '  <Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>\n';
      wb.SheetNames.forEach((name, i) => {
        wbRels += `  <Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>\n`;
      });
      wbRels += '</Relationships>';
      files.push({ name: 'xl/_rels/workbook.xml.rels', data: wbRels });

      // 3. xl/workbook.xml
      let wbXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' +
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">\n' +
        '  <sheets>\n';
      wb.SheetNames.forEach((name, i) => {
        wbXml += `    <sheet name="${escapeXml(name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>\n`;
      });
      wbXml += '  </sheets>\n</workbook>';
      files.push({ name: 'xl/workbook.xml', data: wbXml });

      // 4. xl/styles.xml
      const stylesXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' +
        '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">\n' +
        '  <fonts count="1"><font><sz val="11"/><color theme="1"/><name val="Calibri"/></font></fonts>\n' +
        '  <fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>\n' +
        '  <borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>\n' +
        '  <cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>\n' +
        '  <cellXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/></cellXfs>\n' +
        '</styleSheet>';
      files.push({ name: 'xl/styles.xml', data: stylesXml });

      // 5. Worksheets
      wb.SheetNames.forEach((name, i) => {
        const ws = wb.Sheets[name];
        const rows = ws['!rows'] || [];
        let wsXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' +
          '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">\n' +
          '  <sheetViews><sheetView tabSelected="' + (i === 0 ? '1' : '0') + '" workbookViewId="0" rightToLeft="1"/></sheetViews>\n' +
          '  <sheetData>\n';

        rows.forEach((r, rowIdx) => {
          const rowNum = rowIdx + 1;
          wsXml += `    <row r="${rowNum}">\n`;
          r.forEach((val, colIdx) => {
            const colRef = colToLetter(colIdx) + rowNum;
            const isNum = typeof val === 'number' || (typeof val === 'string' && val.trim() !== '' && !isNaN(Number(val)));
            if (isNum && typeof val === 'number') {
              wsXml += `      <c r="${colRef}"><v>${val}</v></c>\n`;
            } else {
              wsXml += `      <c r="${colRef}" t="inlineStr"><is><t>${escapeXml(val)}</t></is></c>\n`;
            }
          });
          wsXml += '    </row>\n';
        });

        wsXml += '  </sheetData>\n</worksheet>';
        files.push({ name: `xl/worksheets/sheet${i + 1}.xml`, data: wsXml });
      });

      // 6. [Content_Types].xml
      let ctXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n' +
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\n' +
        '  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\n' +
        '  <Default Extension="xml" ContentType="application/xml"/>\n' +
        '  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>\n' +
        '  <Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>\n';
      wb.SheetNames.forEach((name, i) => {
        ctXml += `  <Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>\n`;
      });
      ctXml += '</Types>';
      files.push({ name: '[Content_Types].xml', data: ctXml });

      return makeZip(files);
    },
    writeFile: function (wb, filename) {
      const uint8 = this.buildXlsxUint8Array(wb);
      const blob = new Blob([uint8], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      });
      if (typeof navigator !== 'undefined' && navigator.msSaveOrOpenBlob) {
        navigator.msSaveOrOpenBlob(blob, filename);
        return;
      }
      if (typeof window !== 'undefined' && window.URL && window.URL.createObjectURL) {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        setTimeout(function () {
          document.body.removeChild(a);
          window.URL.revokeObjectURL(url);
        }, 250);
      }
    }
  };

  global.XLSX = XLSX;
})(typeof window !== 'undefined' ? window : globalThis);
